use super::{assert_close, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn watts() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(Luminosity::from_watts(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(Luminosity::from_base(base).as_watts(), back, F64_TOL);
        assert_close(Luminosity::from_watts(v).as_watts(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Luminosity::from_watts(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Luminosity::from_base(base as f32).as_watts() as f64,
            back,
            F32_TOL,
        );
    }
}

